function hammingWeight(n) {
  let count = 0;
  for (let i = 0; i < 32; i++) {
    count += (n >>> i) & 1;
  }
  return count;
}

function hammingWeight(n) {
  let count = 0;
  let val = n >>> 0;
  while (val !== 0) {
    val = (val & (val - 1)) >>> 0;
    count++;
  }
  return count;
}

